// A request spends its CPU like this (measured with --prof):
//   hotFraction = 0.04  -> 4% of steady-state CPU is in the candidate hot loop
//   localSpeedup = 4     -> hand-tuning makes JUST that loop 4x faster
// Amdahl: overall = 1 / ((1 - f) + f / s)
function verdict(hotFraction, localSpeedup) {
  const overall = 1 / ((1 - hotFraction) + hotFraction / localSpeedup);
  const gainPct = Math.round((overall - 1) * 1000) / 10;
  // TODO: print the line below, then print "WORTH IT" if gainPct >= 5 else "PREMATURE"
  // overall=<overall to 3 decimals> gain=<gainPct>%
}
verdict(0.04, 4);
